CREATE TABLE products(id INTEGER PRIMARY KEY, name TEXT NOT NULL CHECK(length(trim(name))>0), price_cents INTEGER NOT NULL CHECK(price_cents>0), pack_size INTEGER NOT NULL CHECK(pack_size>0), min_stock INTEGER NOT NULL CHECK(min_stock>=0), stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0), value_cents INTEGER NOT NULL DEFAULT 0 CHECK(value_cents>=0), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE reservations(product_id INTEGER NOT NULL REFERENCES products(id), owner_type TEXT NOT NULL, owner_id INTEGER NOT NULL, qty INTEGER NOT NULL CHECK(qty>0), PRIMARY KEY(product_id, owner_type, owner_id));
CREATE TABLE stock_movements(id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), moved_at TEXT NOT NULL, qty INTEGER NOT NULL, value_cents INTEGER NOT NULL, kind TEXT NOT NULL, source_id INTEGER, reason TEXT);
CREATE TABLE purchases(id INTEGER PRIMARY KEY, incurred_on TEXT NOT NULL, total_cents INTEGER NOT NULL, reversed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE purchase_items(id INTEGER PRIMARY KEY, purchase_id INTEGER NOT NULL REFERENCES purchases(id), product_id INTEGER NOT NULL REFERENCES products(id), qty INTEGER NOT NULL, total_cents INTEGER NOT NULL, returned_qty INTEGER NOT NULL DEFAULT 0);
CREATE TABLE obligations(id INTEGER PRIMARY KEY, source_type TEXT NOT NULL, source_id TEXT NOT NULL, description TEXT NOT NULL, category TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>0), incurred_on TEXT NOT NULL, due_on TEXT NOT NULL, created_at TEXT NOT NULL, deleted_at TEXT, UNIQUE(source_type,source_id));
CREATE TABLE supplier_credits(id INTEGER PRIMARY KEY, purchase_id INTEGER NOT NULL REFERENCES purchases(id), amount_cents INTEGER NOT NULL CHECK(amount_cents>=0), received_cents INTEGER NOT NULL DEFAULT 0, reason TEXT NOT NULL);

